<template><main class="page assets"><header class="head"><button @click="go('/home')"><i class="fas fa-chevron-right"></i></button><h1>الأصول<span>.</span></h1><button @click="go('/transactions')"><i class="far fa-file-lines"></i></button></header><nav class="tabs"><button v-for="t in tabs" :key="t" :class="{active:t===tab}" @click="tab=t">{{t}}</button></nav><section class="summary"><small>إجمالي الخيارات</small><strong>${{total.toFixed(0)}}</strong><span>(${{total.toFixed(0)}}) ↗</span></section><div class="tools"><button><i class="fas fa-filter"></i></button><button><i class="fas fa-sliders"></i></button><div class="search"><span>رمز أو اسم أو عنوان</span><i class="fas fa-search"></i></div></div><section class="list"><article v-for="c in coins" :key="c.symbol" class="row"><div class="coin" :class="c.class">{{c.mark}}</div><div class="main"><b>{{c.symbol}}</b><span>{{c.price}}</span><small>{{c.change}} <i class="fas fa-arrow-down"></i></small></div><div class="holding"><b>{{c.balance}}</b><span>{{c.usd}}</span></div></article></section></main></template>
<script setup>import {computed,ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import {auth,db} from '../firebase';import {doc,getDoc} from 'firebase/firestore';import {onAuthStateChanged} from 'firebase/auth';const router=useRouter(),go=p=>router.push(p),tab=ref('محفظة'),total=ref(0),tabs=['نظرة عامة','محفظة','بطاقات','قروض','مدخرات'];const coins=[{symbol:'TRX',price:'$0.32',change:'1.66%',balance:'0.000003',usd:'$0.000001',class:'trx',mark:'△'},{symbol:'USDT',price:'$0.99',change:'0.02%',balance:'0',usd:'$0',class:'usdt',mark:'₮'},{symbol:'XRP',price:'$1.32',change:'4.28%',balance:'0',usd:'$0',class:'xrp',mark:'X'},{symbol:'DOGE',price:'$0.08',change:'2.68%',balance:'0',usd:'$0',class:'doge',mark:'Ð'},{symbol:'XLM',price:'$0.17',change:'3.13%',balance:'0',usd:'$0',class:'xlm',mark:'✦'}];onMounted(()=>onAuthStateChanged(auth,async u=>{if(!u)return;try{const s=await getDoc(doc(db,'users',u.uid));if(s.exists()){const d=s.data();total.value=Number(d.balance||0)+Number(d.vipBalance||0)+Number(d.depositBalance||0)}}catch{}}))</script>
